fn empty(n: u8) -> Vec<f64> {
    // Pre-allocate space for exactly `n` elements.
    let mut v = Vec::with_capacity(n as usize);
    
    // Push `0.0` exactly `n` times. At each iteration,
    // v.len() < n holds, and we terminate when we've pushed n elements.
    for _ in 0..n {
        v.push(0.0);
    }
    
    v
}

